# CSV Data Manipulation in JavaScript

## Overview
Working with CSV data in JavaScript involves parsing, transforming, filtering, and aggregating data for visualizations.

## Reading CSV with D3

### Basic CSV Loading
```javascript
d3.csv("data/file.csv").then(data => {
    console.log(data);
    // data is array of objects
    // Each row becomes an object with keys from CSV headers
});
```

### Example CSV Structure
```csv
ticker,sector,marketCap,employees
AAPL,Technology,2676055080960,100000
MSFT,Technology,2252284624896,181000
```

Becomes:
```javascript
[
    { ticker: "AAPL", sector: "Technology", marketCap: "2676055080960", employees: "100000" },
    { ticker: "MSFT", sector: "Technology", marketCap: "2252284624896", employees: "181000" }
]
```

## Data Type Conversion

### Convert Strings to Numbers
```javascript
d3.csv("data/stocks.csv").then(data => {
    data.forEach(d => {
        d.marketCap = +d.marketCap;  // Unary plus converts to number
        d.employees = +d.employees;
        // or use parseFloat(d.marketCap)
    });
});
```

### Automatic Type Conversion
```javascript
d3.csv("data/stocks.csv", d3.autoType).then(data => {
    // d3.autoType automatically converts numbers, booleans, dates
});
```

### Custom Row Converter
```javascript
d3.csv("data/stocks.csv", row => {
    return {
        ticker: row.ticker,
        sector: row.sector,
        marketCap: row.marketCap ? +row.marketCap : null,
        name: row["full name"],  // Handle spaces in column names
        employees: +row.fullTimeEmployees
    };
}).then(data => {
    console.log(data);
});
```

## Filtering Data

### Filter by Condition
```javascript
const techStocks = data.filter(d => d.sector === "Technology");
const largeStocks = data.filter(d => d.marketCap > 1e12);
```

### Filter with Multiple Conditions
```javascript
const filtered = data.filter(d =>
    d.sector === "Technology" &&
    d.marketCap > 1e11 &&
    d.employees > 50000
);
```

### Filter Out Null/Undefined Values
```javascript
const validData = data.filter(d =>
    d.marketCap !== null &&
    d.marketCap !== undefined &&
    !isNaN(d.marketCap)
);
```

## Transforming Data

### Map to New Structure
```javascript
const simplified = data.map(d => ({
    symbol: d.ticker,
    value: d.marketCap / 1e9,  // Convert to billions
    category: d.sector
}));
```

### Add Calculated Fields
```javascript
data.forEach(d => {
    d.marketCapBillions = d.marketCap / 1e9;
    d.revenuePerEmployee = d.revenue / d.employees;
});
```

## Grouping Data

### Using d3.group (returns Map)
```javascript
const bySector = d3.group(data, d => d.sector);
// Map { "Technology" => [...], "Finance" => [...] }

// Access groups
bySector.get("Technology");  // Array of tech stocks
```

### Multiple Grouping Levels
```javascript
const nested = d3.group(
    data,
    d => d.sector,      // First level
    d => d.country      // Second level
);
// Map { "Technology" => Map { "USA" => [...], "Taiwan" => [...] } }
```

### Using d3.rollup (aggregate)
```javascript
const totalBySector = d3.rollup(
    data,
    v => d3.sum(v, d => d.marketCap),  // Aggregation function
    d => d.sector                       // Grouping key
);
// Map { "Technology" => 123456789, "Finance" => 987654321 }
```

## Aggregation Functions

### Sum, Mean, Max, Min
```javascript
const totalMarketCap = d3.sum(data, d => d.marketCap);
const avgMarketCap = d3.mean(data, d => d.marketCap);
const maxMarketCap = d3.max(data, d => d.marketCap);
const minMarketCap = d3.min(data, d => d.marketCap);

// Get both min and max at once
const [min, max] = d3.extent(data, d => d.marketCap);
```

### Count by Category
```javascript
const countBySector = d3.rollup(
    data,
    v => v.length,  // Count items in each group
    d => d.sector
);
```

### Custom Aggregation
```javascript
const avgEmployeesBySector = d3.rollup(
    data,
    v => d3.mean(v, d => d.employees),
    d => d.sector
);
```

## Sorting Data

### Sort by Number
```javascript
data.sort((a, b) => d3.descending(a.marketCap, b.marketCap));  // Largest first
data.sort((a, b) => d3.ascending(a.marketCap, b.marketCap));   // Smallest first
```

### Sort by String
```javascript
data.sort((a, b) => d3.ascending(a.ticker, b.ticker));  // Alphabetical
```

### Multiple Sort Criteria
```javascript
data.sort((a, b) => {
    // First by sector
    const sectorCompare = d3.ascending(a.sector, b.sector);
    if (sectorCompare !== 0) return sectorCompare;
    // Then by market cap
    return d3.descending(a.marketCap, b.marketCap);
});
```

## Getting Unique Values

### Extract Unique Sectors
```javascript
const uniqueSectors = [...new Set(data.map(d => d.sector))];
// or
const uniqueSectors = Array.from(new Set(data.map(d => d.sector)));
```

### Get Top N Items
```javascript
const top10 = data
    .sort((a, b) => d3.descending(a.marketCap, b.marketCap))
    .slice(0, 10);
```

## Joining Multiple CSV Files

### Load and Merge
```javascript
Promise.all([
    d3.csv("data/stocks.csv"),
    d3.csv("data/prices.csv")
]).then(([stocks, prices]) => {
    // Create a map for quick lookup
    const stockMap = new Map(stocks.map(d => [d.ticker, d]));

    // Add stock info to prices
    prices.forEach(p => {
        const stock = stockMap.get(p.ticker);
        if (stock) {
            p.sector = stock.sector;
            p.marketCap = stock.marketCap;
        }
    });

    console.log(prices);
});
```

## Handling Missing Data

### Replace Null with Default
```javascript
data.forEach(d => {
    d.marketCap = d.marketCap || 0;  // Default to 0 if null/undefined
    d.sector = d.sector || "Unknown";
});
```

### Filter Out Missing Data
```javascript
const complete = data.filter(d =>
    d.ticker && d.sector && d.marketCap
);
```

## Number Formatting

### Format Large Numbers
```javascript
function formatMarketCap(value) {
    if (!value) return "N/A";
    if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
    if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
    return value.toFixed(0);
}

// Usage
data.forEach(d => {
    d.marketCapFormatted = formatMarketCap(d.marketCap);
});
```

### Using D3 Formatters
```javascript
const formatNumber = d3.format(",");          // 1,234,567
const formatDecimal = d3.format(",.2f");      // 1,234.56
const formatSI = d3.format(".2s");            // 1.2M
const formatPercent = d3.format(".1%");       // 12.3%
```

## Complete Example: Stock Data Processing

```javascript
Promise.all([
    d3.csv("data/stock-descriptions.csv"),
    d3.csv("data/indiv-stock/AAPL.csv")
]).then(([stocks, prices]) => {
    // Clean and transform stock data
    stocks.forEach(d => {
        d.marketCap = d.marketCap ? +d.marketCap : null;
        d.employees = d.fullTimeEmployees ? +d.fullTimeEmployees : null;
        d.name = d["full name"];
    });

    // Filter out ETFs (no market cap)
    const companies = stocks.filter(d => d.marketCap !== null);

    // Get unique sectors
    const sectors = [...new Set(companies.map(d => d.sector))];

    // Calculate totals by sector
    const sectorTotals = d3.rollup(
        companies,
        v => ({
            count: v.length,
            totalMarketCap: d3.sum(v, d => d.marketCap),
            avgMarketCap: d3.mean(v, d => d.marketCap)
        }),
        d => d.sector
    );

    // Sort by market cap
    companies.sort((a, b) => d3.descending(a.marketCap, b.marketCap));

    // Format for display
    companies.forEach(d => {
        d.marketCapFormatted = formatMarketCap(d.marketCap);
    });

    console.log("Processed data:", companies);
    console.log("Sector analysis:", sectorTotals);

    // Create visualization
    createVisualization(companies, sectors);

}).catch(error => {
    console.error("Error loading data:", error);
});

function formatMarketCap(value) {
    if (!value) return "N/A";
    if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
    return (value / 1e6).toFixed(2) + "M";
}
```

## Best Practices

1. **Always convert types** - CSV data is strings by default
2. **Handle missing data** - Check for null/undefined/NaN values
3. **Use d3.autoType** for automatic conversion when appropriate
4. **Filter early** - Remove invalid data before processing
5. **Use Maps for lookups** - More efficient than array.find()
6. **Validate data** - Check ranges and expected values
7. **Format for display** - Keep raw values for calculations, formatted for UI
8. **Use descriptive variable names** - Makes code more maintainable

