input.content:
// Global variables
let stockData = [];
let selectedTicker = null;
const sectorColors = {
    "Information Technology": "#3498db",
    "Industry": "#2ecc71",
    "Energy": "#f39c12",
    "Financial": "#e74c3c",
    "ETF": "#95a5a6"
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return "N/A";
    if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
    if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
    return value.toFixed(0);
}

// Initialize visualization
function initVisualization() {
    d3.csv("data/stock-descriptions.csv").then(data => {
        // Process data
        data.forEach(d => {
            d.marketCap = d.marketCap && d.marketCap !== "" ? +d.marketCap : null;
            d.name = d["full name"];
            d.isETF = d.marketCap === null;
        });

        stockData = data;

        // Create visualizations
        createBubbleChart(data);
        createTable(data);
    }).catch(error => {
        console.error("Error loading data:", error);
        document.getElementById("app").innerHTML +=
            "<p style='color: red; text-align: center;'>Error loading data. Please check the console.</p>";
    });
}

// Create bubble chart with force simulation
function createBubbleChart(data) {
    const container = document.getElementById("bubble-chart");
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Clear any existing SVG
    d3.select("#bubble-chart").selectAll("*").remove();

    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    // Create tooltip
    const tooltip = d3.select("body")
        .append("div")
        .attr("class", "tooltip");

    // Get unique sectors
    const sectors = [...new Set(data.map(d => d.sector))];

    // Define cluster centers for each sector
    const clusterCenters = {
        "Information Technology": { x: width * 0.25, y: height * 0.3 },
        "Industry": { x: width * 0.75, y: height * 0.3 },
        "Energy": { x: width * 0.5, y: height * 0.7 },
        "Financial": { x: width * 0.15, y: height * 0.7 },
        "ETF": { x: width * 0.85, y: height * 0.7 }
    };

    // Radius scale (sqrt for area proportional to value)
    const radiusScale = d3.scaleSqrt()
        .domain([0, d3.max(data.filter(d => !d.isETF), d => d.marketCap)])
        .range([8, 50]);

    // Assign radius to each data point
    data.forEach(d => {
        if (d.isETF) {
            d.radius = 15; // Uniform size for ETFs
        } else {
            d.radius = radiusScale(d.marketCap);
        }
    });

    // Create force simulation
    const simulation = d3.forceSimulation(data)
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.5))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.5))
        .force("collide", d3.forceCollide(d => d.radius + 2))
        .force("charge", d3.forceManyBody().strength(-8))
        .on("tick", ticked);

    // Create bubbles
    const bubbles = svg.selectAll(".bubble")
        .data(data)
        .join("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => sectorColors[d.sector] || "#999")
        .on("mouseover", function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style("visibility", "visible")
                    .html(`
                        <strong>${d.ticker}</strong>
                        <div>${d.name}</div>
                        <div>Sector: ${d.sector}</div>
                    `);
            }
        })
        .on("mousemove", function(event) {
            tooltip
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 20) + "px");
        })
        .on("mouseout", function() {
            tooltip.style("visibility", "hidden");
        })
        .on("click", function(event, d) {
            selectStock(d.ticker);
        });

    // Create labels
    const labels = svg.selectAll(".bubble-label")
        .data(data)
        .join("text")
        .attr("class", "bubble-label")
        .attr("font-size", d => Math.min(d.radius / 2.5, 12) + "px")
        .text(d => d.ticker);

    // Update positions on each tick
    function ticked() {
        bubbles
            .attr("cx", d => d.x)
            .attr("cy", d => d.y);

        labels
            .attr("x", d => d.x)
            .attr("y", d => d.y + 4);
    }

    // Create legend
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", `translate(20, 20)`);

    sectors.forEach((sector, i) => {
        const legendItem = legend.append("g")
            .attr("class", "legend-item")
            .attr("transform", `translate(0, ${i * 25})`);

        legendItem.append("circle")
            .attr("class", "legend-color")
            .attr("cx", 10)
            .attr("cy", 0)
            .attr("r", 8)
            .attr("fill", sectorColors[sector] || "#999");

        legendItem.append("text")
            .attr("class", "legend-label")
            .attr("x", 25)
            .attr("y", 4)
            .text(sector);
    });

    // Store references for selection updates
    window.bubbles = bubbles;
}

// Create table
function createTable(data) {
    const tableContainer = d3.select("#table-container");

    const table = tableContainer.append("table");

    // Create header
    const thead = table.append("thead");
    thead.append("tr")
        .selectAll("th")
        .data(["Ticker", "Company Name", "Sector", "Market Cap"])
        .join("th")
        .text(d => d);

    // Create body
    const tbody = table.append("tbody");

    const rows = tbody.selectAll("tr")
        .data(data)
        .join("tr")
        .on("click", function(event, d) {
            selectStock(d.ticker);
        });

    // Add cells
    rows.each(function(d) {
        const row = d3.select(this);

        // Ticker
        row.append("td").text(d.ticker);

        // Company name
        row.append("td").text(d.name || "");

        // Sector with color indicator
        const sectorCell = row.append("td");
        sectorCell.append("span")
            .attr("class", "sector-indicator")
            .style("background-color", sectorColors[d.sector] || "#999");
        sectorCell.append("span").text(d.sector || "");

        // Market cap
        row.append("td").text(formatMarketCap(d.marketCap));
    });

    // Store reference for selection updates
    window.tableRows = rows;
}

// Handle selection (both bubble and table)
function selectStock(ticker) {
    selectedTicker = ticker;

    // Update bubbles
    if (window.bubbles) {
        window.bubbles
            .classed("selected", d => d.ticker === ticker)
            .attr("stroke", d => d.ticker === ticker ? "#000" : "#fff")
            .attr("stroke-width", d => d.ticker === ticker ? 3 : 1.5);
    }

    // Update table rows
    if (window.tableRows) {
        window.tableRows.classed("highlight", d => d.ticker === ticker);

        // Scroll to highlighted row
        const highlightedRow = document.querySelector("tr.highlight");
        if (highlightedRow) {
            highlightedRow.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }
}

// Initialize on page load
document.addEventListener("DOMContentLoaded", initVisualization);

